using System.Text.Json;
using VisionFramework;
using VisionCore;
using VisionWorkbench;
namespace VisionEditor;
sealed class ToolDebugWindow:Form {
 readonly Dictionary<string,Control> editors=new();readonly ImageCanvas preview=new(){CheckerboardWhenEmpty=true};readonly TextBox result=new(){Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,BackColor=Color.FromArgb(35,35,35),ForeColor=Color.Silver};readonly Func<Dictionary<string,JsonElement>,Task<NodeRunRecord>> execute;readonly Action<Dictionary<string,JsonElement>> apply;
 internal ToolDebugWindow(NodeDocument node,ModuleDescriptor descriptor,Dictionary<string,string> labels,Action<Dictionary<string,JsonElement>> apply,Func<Dictionary<string,JsonElement>,Task<NodeRunRecord>> execute,IEnumerable<(string Id,string Name)> sources,Action<string> bind,Func<GrayImage?>? inputImage=null){this.apply=apply;this.execute=execute;AutoScaleMode=AutoScaleMode.None;Text=node.Name+" · 调试";Width=1100;Height=740;StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(35,35,35);ForeColor=Color.Silver;Font=new Font("Microsoft YaHei UI",10.5f);var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1000,650),SplitterDistance=630,BackColor=BackColor};split.Panel1.Controls.Add(preview);var tabs=new DarkTabControl{Dock=DockStyle.Fill,DrawMode=TabDrawMode.OwnerDrawFixed,SizeMode=TabSizeMode.Fixed,ItemSize=new Size(100,36)};tabs.DrawItem+=(_,e)=>{using var b=new SolidBrush(e.Index==tabs.SelectedIndex?Color.FromArgb(76,76,76):BackColor);e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,tabs.TabPages[e.Index].Text,Font,e.Bounds,ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);};var basic=new TabPage("基本参数"){BackColor=BackColor};var run=new TabPage("运行参数"){BackColor=BackColor};var output=new TabPage("结果显示"){BackColor=BackColor};var basicRows=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(10)};var runRows=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(10)};basic.Controls.Add(basicRows);run.Controls.Add(runRows);output.Controls.Add(result);tabs.TabPages.Add(basic);if(node.ModuleId!="vision.image-file")tabs.TabPages.Add(run);tabs.TabPages.Add(output);split.Panel2.Controls.Add(tabs);if(descriptor.Inputs.Any(p=>p.Kind==DataKind.GrayImage)){basicRows.Controls.Add(new Label{Text="图像源 · 输入图像订阅",AutoSize=true});var choice=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};foreach(var source in sources)choice.Items.Add(new SourceChoice(source.Id,source.Name));basicRows.Controls.Add(choice);var subscribe=new Button{Text="订阅图像",Width=120,Height=36};subscribe.Click+=(_,_)=>{try{if(choice.SelectedItem is SourceChoice source)bind(source.Id);}catch(Exception ex){MessageBox.Show(this,ex.Message);}};basicRows.Controls.Add(subscribe);}
 foreach(var spec in descriptor.Parameters){var row=new FlowLayoutPanel{Width=320,Height=42};row.Controls.Add(new Label{Text=labels.GetValueOrDefault(spec.Name,spec.Name),Width=130,Height=32,TextAlign=ContentAlignment.MiddleLeft});node.Parameters.TryGetValue(spec.Name,out var value);Control editor;if(spec.Kind is ParameterKind.Integer or ParameterKind.Number){var n=new NumericUpDown{Width=165,DecimalPlaces=spec.Kind==ParameterKind.Integer?0:3,Minimum=(decimal)(spec.Minimum??-10000000),Maximum=(decimal)(spec.Maximum??10000000)};if(value.ValueKind==JsonValueKind.Number)n.Value=Math.Clamp(value.GetDecimal(),n.Minimum,n.Maximum);editor=n;}else if(spec.Name=="Polarity"){var c=new ComboBox{Width=165,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(new object[]{"Both","DarkToLight","LightToDark"});c.SelectedItem=value.ValueKind==JsonValueKind.String?value.GetString():"Both";editor=c;}else editor=new TextBox{Width=165,Text=value.ValueKind==JsonValueKind.String?value.GetString():value.ToString()};editor.Tag=spec;editors[spec.Name]=editor;row.Controls.Add(editor);(node.ModuleId=="vision.image-file"?basicRows:runRows).Controls.Add(row);if(spec.Name=="Path"){var choose=new Button{Text="添加本地图像…",Width=165,Height=36};choose.Click+=(_,_)=>{using var file=new OpenFileDialog{Filter="BMP 图像|*.bmp"};if(file.ShowDialog(this)==DialogResult.OK)((TextBox)editor).Text=file.FileName;};basicRows.Controls.Add(choose);}}
 preview.CenterPicked=(x,y)=>{if(editors.TryGetValue("CenterX",out var cx)&&editors.TryGetValue("CenterY",out var cy)){((NumericUpDown)cx).Value=(decimal)x;((NumericUpDown)cy).Value=(decimal)y;}};var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="应用",Width=100,Height=36};save.Click+=(_,_)=>{try{apply(ReadValues());}catch(Exception ex){MessageBox.Show(this,ex.Message);}};var start=new Button{Text="单次运行",Width=120,Height=36};start.Click+=async(_,_)=>{start.Enabled=false;try{var record=await execute(ReadValues());result.Text=record.Status+" · "+record.ElapsedMilliseconds.ToString("F2")+" ms\r\n"+record.Message;foreach(var pair in record.Outputs)result.AppendText("\r\n"+pair.Key+": "+pair.Value.Value);var image=record.Outputs.Values.FirstOrDefault(v=>v.Kind==DataKind.GrayImage);var gray=image?.As<GrayImage>()??inputImage?.Invoke();if(gray is not null)preview.SetImage(gray);var circle=record.Outputs.Values.FirstOrDefault(v=>v.Kind==DataKind.Circle);if(circle is not null)preview.SetOverlay(null,new CircleDetectionResult(CircleDetectionStatus.Success,circle.As<CircleFit>(),Array.Empty<Point2>(),0));}catch(Exception ex){result.Text=ex.Message;}finally{start.Enabled=true;}};footer.Controls.Add(save);footer.Controls.Add(start);Controls.Add(split);Controls.Add(footer);}
 internal Dictionary<string,JsonElement> ReadValues()=>editors.ToDictionary(e=>e.Key,e=>e.Value switch{NumericUpDown n when ((ParameterDescriptor)n.Tag!).Kind==ParameterKind.Integer=>JsonSerializer.SerializeToElement((int)n.Value),NumericUpDown n=>JsonSerializer.SerializeToElement((double)n.Value),ComboBox c=>JsonSerializer.SerializeToElement(c.SelectedItem?.ToString()??""),_=>JsonSerializer.SerializeToElement(e.Value.Text)});
 sealed record SourceChoice(string Id,string Name){public override string ToString()=>Name;}
}
